import{_ as e,b as n,c as s,d as l}from"./chunks/framework.D4cM_aKq.js";const h=JSON.parse('{"title":"从零搭建一座数字书斋","description":"用 Vue、Markdown 和自动部署，为自己的项目与思考留一个长期的入口。","frontmatter":{"layout":"article","title":"从零搭建一座数字书斋","description":"用 Vue、Markdown 和自动部署，为自己的项目与思考留一个长期的入口。","date":"2026-10-17","category":"前端开发","directory":"站点实践","tags":["Vue 3","VitePress","GitHub Pages"],"featured":true,"sample":true},"headers":[{"level":2,"title":"从内容开始","slug":"从内容开始","link":"#从内容开始","children":[]},{"level":2,"title":"为什么使用静态生成","slug":"为什么使用静态生成","link":"#为什么使用静态生成","children":[]},{"level":2,"title":"内容如何组织","slug":"内容如何组织","link":"#内容如何组织","children":[]},{"level":2,"title":"自动部署的过程","slug":"自动部署的过程","link":"#自动部署的过程","children":[]},{"level":2,"title":"给后续维护留出空间","slug":"给后续维护留出空间","link":"#给后续维护留出空间","children":[]},{"level":2,"title":"延伸阅读","slug":"延伸阅读","link":"#延伸阅读","children":[]}],"relativePath":"journal/frontend/digital-study.md","filePath":"journal/frontend/digital-study.md"}'),t={name:"journal/frontend/digital-study.md"};function i(r,a,p,o,d,u){return n(),s("div",null,[...a[0]||(a[0]=[l(`<h2 id="从内容开始" tabindex="-1">从内容开始 <a class="header-anchor" href="#从内容开始" aria-label="Permalink to &quot;从内容开始&quot;">​</a></h2><p>搭建个人网站时，可以先想清楚三个问题：希望读者了解什么、希望读者找到什么，以及自己以后怎样更新内容。</p><p>对一个以项目展示和技术笔记为主的网站而言，个人介绍、作品列表和知识目录就是最重要的入口。</p><h2 id="为什么使用静态生成" tabindex="-1">为什么使用静态生成 <a class="header-anchor" href="#为什么使用静态生成" aria-label="Permalink to &quot;为什么使用静态生成&quot;">​</a></h2><p>文章在构建时生成 HTML，访问者打开链接即可读取正文。需要交互时，再由 Vue 接管筛选、搜索和主题切换。</p><p>这种结构适合内容在发布时已知、不同访问者看到相同正文的网站。修改内容后重新构建，即可发布新版本。</p><h2 id="内容如何组织" tabindex="-1">内容如何组织 <a class="header-anchor" href="#内容如何组织" aria-label="Permalink to &quot;内容如何组织&quot;">​</a></h2><p>目录负责长期结构，标签负责跨主题连接。比如“前端开发 / 站点实践”可以收藏建站笔记，而“GitHub Pages”标签可以同时出现在部署文章与个人站点项目中。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>├─ projects/       # 项目介绍</span></span>
<span class="line"><span>├─ journal/        # 知识与笔记</span></span>
<span class="line"><span>├─ public/         # 头像、图片和字体</span></span>
<span class="line"><span>└─ .vitepress/     # 页面主题和站点配置</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="自动部署的过程" tabindex="-1">自动部署的过程 <a class="header-anchor" href="#自动部署的过程" aria-label="Permalink to &quot;自动部署的过程&quot;">​</a></h2><p>提交到主分支后，GitHub Actions 安装依赖、检查类型、构建页面，并将产物发布到 GitHub Pages。</p><p>仓库设置中的 Pages 发布来源需要选择 <strong>GitHub Actions</strong>。本项目的使用说明写在仓库 README 中。</p><h2 id="给后续维护留出空间" tabindex="-1">给后续维护留出空间 <a class="header-anchor" href="#给后续维护留出空间" aria-label="Permalink to &quot;给后续维护留出空间&quot;">​</a></h2><p>先保持内容格式一致，再逐步完善界面。对新项目写下背景、方法、结果与反思；对新笔记写清问题、结论和适用条件。</p><blockquote><p>一个好的个人网站，不必一次写完。让它有一个清楚的开始，然后慢慢生长。</p></blockquote><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/projects/web/shanshui.html">项目示例：山水之间</a></li><li><a href="/journal/notes/knowledge-map.html">让笔记成为自己的知识地图</a></li></ul>`,17)])])}const b=e(t,[["render",i]]);export{h as __pageData,b as default};
